script:
frappe.ui.form.on('Beneficiary Request', {
    refresh: function(frm) {
        if (frm.doc.status === 'Approved For Aid') {
            frm.add_custom_button(__('Create Aid'), function() {
                frappe.new_doc('Beneficiary Aid', {
                 request_category: frm.doc.request_category,
                 beneficiaries: frm.doc.beneficiaries,
                 beneficiary_request: frm.doc.name,
                 suggested_amount: frm.doc.approved_amount

                });
            });
   }
}
});

frappe.ui.form.on('Beneficiaries Registration', {
    // refresh: function(frm) {
    //     if (frm.doc.workflow_state === 'Accepted') {
    //         frm.fields.forEach(function(field) {
    //             if (field.df.fieldname !== "custom_notes") {
    //                 field.df.read_only = 1;
    //             }
    //         });
    //         frm.refresh_fields();
    //     } else {
    //         frm.fields.forEach(function(field) {
    //             field.df.read_only = 0;
    //         });
    //         frm.refresh_fields();
    //     }
    // },
    
    refresh: function(frm) {
        frm.fields.forEach(function(field) {
            if (field.df.fieldname !== "custom_notes") {
                field.df.read_only = 1;
            }
        });
        frm.refresh_fields();
    },
    
    before_save: function(frm) {
        if (frm.doc.workflow_state === 'Accepted' && frm.doc.custom_notes === "") {
            frappe.msgprint(__('Cannot save the document in "Accepted" state.'));
            frappe.validated = false;
        }
    }
});

frappe.ui.form.on('Beneficiaries Registration', {

    validate: function(frm) {
        let dob = frm.doc.date_of_birth;
        if (dob) {
            let today = new Date();
            let birthDate = new Date(dob);
            let age = today.getFullYear() - birthDate.getFullYear();

            let monthDifference = today.getMonth() - birthDate.getMonth();
            if (monthDifference < 0 || (monthDifference === 0 && today.getDate() < birthDate.getDate())) {
                age--;
            }

            if (age < 21) {
                frappe.msgprint('Must be 21 years of age or older.');
                frm.set_value('date_of_birth', '');
                frappe.validated = false;
            }
        }
    }

})
